import { render, screen } from '@testing-library/react';
import UserStats from './UserStats';
import { describe, it, expect } from 'vitest';

describe('UserStats', () => {
  it('displays correct statistics for a mix of active and inactive users', () => {
    const users = [
      { id: 1, name: 'User 1', isActive: true },
      { id: 2, name: 'User 2', isActive: false },
      { id: 3, name: 'User 3', isActive: true },
      { id: 4, name: 'User 4', isActive: false },
      { id: 5, name: 'User 5', isActive: true },
    ];
    // 3 active, 2 inactive. Total 5. 3/5 = 60%

    render(<UserStats users={users} />);

    expect(screen.getByText(/Active Users: 3/i)).toBeDefined();
    expect(screen.getByText(/Inactive Users: 2/i)).toBeDefined();
    expect(screen.getByText(/Active Percentage: 60.0%/i)).toBeDefined();
  });

  it('displays 0% when there are no users', () => {
    render(<UserStats users={[]} />);
    expect(screen.getByText(/Active Users: 0/i)).toBeDefined();
    expect(screen.getByText(/Inactive Users: 0/i)).toBeDefined();
    expect(screen.getByText(/Active Percentage: 0.0%/i)).toBeDefined();
  });

  it('displays 100% when all users are active', () => {
    const users = [
        { id: 1, name: 'User 1', isActive: true },
    ];
    render(<UserStats users={users} />);
    expect(screen.getByText(/Active Percentage: 100.0%/i)).toBeDefined();
  });

  it('displays 0% when all users are inactive', () => {
      const users = [
          { id: 1, name: 'User 1', isActive: false },
      ];
      render(<UserStats users={users} />);
      expect(screen.getByText(/Active Percentage: 0.0%/i)).toBeDefined();
  });
});

